from itertools import combinations


def _route_solver(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bits.get(source, 0)
        start = data["start"]
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        initial = (source, initial_mask, 0)
        distances = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full
                    and (not exact_coupons or used == coupons)):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bits.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                               next_mask, next_used))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, mode):
        quotient, remainder = divmod(numerator, 10000)
        if mode == "half_up" and remainder >= 5000:
            quotient += 1
        return quotient

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(raw * event.get("tax_bp", 0), mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|"
                   + event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial_constraints = {
            name: [tuple(bounds)] for name, bounds in data["roots"].items()
        }
        best_vector = None
        best_versions = None

        def is_acyclic(edges):
            active = set()
            done = set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, ()):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(assigned, constraints, edges):
            nonlocal best_vector, best_versions
            unresolved = [name for name in constraints if name not in assigned]
            if not unresolved:
                if not is_acyclic(edges):
                    return
                vector = tuple(assigned.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_versions = dict(assigned)
                return

            name = unresolved[0]
            low = max(bounds[0] for bounds in constraints[name])
            high = min(bounds[1] for bounds in constraints[name])
            forbidden = set(blocked.get(name, []))
            if name in pins:
                forbidden_versions = forbidden
                candidates = [row for row in packages.get(name, [])
                              if row["version"] == pins[name]
                              and low <= row["version"] <= high
                              and row["version"] not in forbidden_versions]
            else:
                candidates = [row for row in packages.get(name, [])
                              if low <= row["version"] <= high
                              and row["version"] not in forbidden]

            for row in candidates:
                version = row["version"]
                next_assigned = dict(assigned)
                next_assigned[name] = version
                next_constraints = {key: list(value)
                                    for key, value in constraints.items()}
                next_edges = {key: set(value) for key, value in edges.items()}
                next_edges.setdefault(name, set())
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    interval = (dep["min"], dep["max"])
                    next_constraints.setdefault(dep_name, []).append(interval)
                    next_edges[name].add(dep_name)
                    if dep_name in next_assigned:
                        dep_version = next_assigned[dep_name]
                        if not all(lo <= dep_version <= hi
                                   for lo, hi in next_constraints[dep_name]):
                            valid = False
                            break
                        if dep_version in blocked.get(dep_name, []):
                            valid = False
                            break
                        if dep_name in pins and dep_version != pins[dep_name]:
                            valid = False
                            break
                if valid:
                    search(next_assigned, next_constraints, next_edges)

        search({}, initial_constraints, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for selected in combinations(options, k):
            ids = [job["id"] for job in selected]
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in data.get("quotas", {}).items()):
                continue

            ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[j]["start"]
                   for i in range(len(ordered))
                   for j in range(i + 1, len(ordered))):
                continue

            value = sum(job["value"] for job in selected)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value
                    or (value == best_value and sorted_ids < best_ids)):
                best_value = value
                best_ids = sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


